// Renders the product cards and the product dialog from products.js
function openProduct(p){const img=document.querySelector('#modalimage');img.hidden=!p.image;if(p.image){img.src=p.image;img.alt=p.imageAlt||p.name}else{img.removeAttribute('src');img.alt=''};document.querySelector('#modaltype').textContent=p.label;document.querySelector('#modaltitle').textContent=p.name;document.querySelector('#modaldesc').textContent=p.description;document.querySelector('#modalprice').textContent='Draft price '+p.price;document.querySelector('#modalformat').textContent=p.format||p.label;for(const [id,key] of [['availability','availability'],['compat','compat'],['included','included'],['delivery','delivery'],['license','license']])document.querySelector('#modal'+id).textContent=p[key]||'To be confirmed';document.querySelector('#dialog').showModal()}

const grid=document.querySelector('#products');function render(filter='all'){grid.innerHTML='';products.filter(p=>filter==='all'||p.type===filter).forEach(p=>{let c=document.createElement('article');c.className='card';const art=p.image?`<div class="art has-image"><img src="${p.image}" alt="${p.imageAlt||p.name}" loading="lazy"></div>`:`<div class="art ${p.art}" aria-hidden="true"><div class="art-inner"><small>Syncronicity / Digital tools</small><strong>${p.name}</strong></div></div>`;c.innerHTML=`${art}<div class="card-meta"><span>${p.label}</span><span>Draft ${p.price}</span></div><h3>${p.name}</h3><p>${p.description}</p><p class="availability">${p.availability}</p><button>Explore product</button>`;c.querySelector('button').addEventListener('click',()=>openProduct(p));grid.appendChild(c)})}render();document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true');render(b.dataset.filter)}));document.querySelector('.close').addEventListener('click',()=>document.querySelector('#dialog').close());
